import hashlib, math, random

class Bloom:
    def __init__(self, m, k):
        self.m, self.k = m, k
        self.bits = [0] * m

    def _idx(self, item: bytes):
        # famiglia di k funzioni hash: h_i(x) = SHA256(i || x) mod m
        return [int.from_bytes(hashlib.sha256(bytes([i]) + item).digest(), 'big') % self.m
                for i in range(self.k)]

    def add(self, item: bytes):
        for j in self._idx(item):
            self.bits[j] = 1

    def might_contain(self, item: bytes) -> bool:
        return all(self.bits[j] for j in self._idx(item))

random.seed(11)
def fake_pkh():
    return random.randbytes(20)

wallet = [fake_pkh() for _ in range(20)]          # n = 20 indirizzi del client SPV
for m, k in [(64, 2), (200, 5), (1000, 7)]:
    bf = Bloom(m, k)
    for a in wallet:
        bf.add(a)
    assert all(bf.might_contain(a) for a in wallet)   # nessun falso negativo
    others = [fake_pkh() for _ in range(20000)]       # output di transazioni estranee
    fp = sum(bf.might_contain(o) for o in others) / len(others)
    teo = (1 - math.exp(-k * len(wallet) / m)) ** k
    print(f"m={m:4d} k={k}  FP misurata={fp:.4f}  teorica={teo:.2e}  "
          f"tx estranee inviate su 20000: {int(fp*20000)}")

