import hashlib

def sha256(b): return hashlib.sha256(b).digest()
def hash160(b): return hashlib.new('ripemd160', sha256(b)).digest()

# firme giocattolo (solo per la struttura, NON sicure)
def toy_sign(pk, msg): return sha256(b"sig" + pk + msg)
def toy_verify(sig, pk, msg): return sig == toy_sign(pk, msg)

def num(b: bytes) -> int: return int.from_bytes(b, 'little') if b else 0
def enc(n: int) -> bytes: return n.to_bytes((n.bit_length() + 7) // 8 or 1, 'little') if n else b''

def run(script, stack, tx):
    """Interprete minimo. script: lista di opcode (str) o dati (bytes/int).
    tx: dict con 'msg' (dati firmati) e 'locktime'."""
    exec_stack = []                              # rami IF attivi/inattivi
    for op in script:
        active = all(exec_stack)
        if op == 'OP_IF':
            exec_stack.append(num(stack.pop()) != 0 if active else False); continue
        if op == 'OP_ELSE':
            exec_stack[-1] = not exec_stack[-1]; continue
        if op == 'OP_ENDIF':
            exec_stack.pop(); continue
        if not active:
            continue
        if isinstance(op, (bytes, int)):
            stack.append(op if isinstance(op, bytes) else enc(op))
        elif op == 'OP_SIZE':
            stack.append(enc(len(stack[-1])))
        elif op == 'OP_EQUALVERIFY':
            a, b = stack.pop(), stack.pop()
            if a != b: return False, "EQUALVERIFY fallito"
        elif op == 'OP_SHA256':
            stack.append(sha256(stack.pop()))
        elif op == 'OP_DUP':
            stack.append(stack[-1])
        elif op == 'OP_HASH160':
            stack.append(hash160(stack.pop()))
        elif op == 'OP_CHECKLOCKTIMEVERIFY':
            if tx['locktime'] < num(stack[-1]): return False, "locktime non raggiunto"
        elif op == 'OP_DROP':
            stack.pop()
        elif op == 'OP_CHECKSIG':
            pk, sig = stack.pop(), stack.pop()
            stack.append(b'\x01' if toy_verify(sig, pk, tx['msg']) else b'')
        else:
            raise ValueError(op)
    ok = bool(stack) and num(stack[-1]) != 0
    return ok, "OK" if ok else "FALSE in cima allo stack"

