# Simulazione di un atomic swap BTC <-> ZEN con HTLC (tempi in ore).
# Alice crea il suo HTLC a t=0 (scade a T_A), Bob il suo a t=1 (scade a 1+T_B).
# Alice sceglie quando rivelare il segreto (r) e se riprendersi prima i BTC scaduti.
# Bob, appena vede il segreto, impiega DELAY ore per far confermare il suo riscatto.

DELAY = 1.0

def outcome(T_A, T_B, r, alice_refunds_first):
    expire_A, expire_B = 0 + T_A, 1 + T_B
    alice, bob = [], []
    # 1) Alice può rimborsarsi solo dopo expire_A
    refunded = alice_refunds_first and r >= expire_A
    if refunded:
        alice.append("1 BTC (rimborso)")
    # 2) Alice riscatta gli ZEN rivelando s, solo prima della scadenza di Bob
    if r < expire_B:
        alice.append("200 ZEN")
        # 3) Bob usa s sul contratto di Alice, se è ancora lì e non è scaduto
        if not refunded and r + DELAY < expire_A:
            bob.append("1 BTC")
        elif not refunded:
            alice.append("1 BTC (rimborso, Bob in ritardo)")
    else:
        bob.append("200 ZEN (rimborso)")
        if not refunded:
            alice.append("1 BTC (rimborso)")
    return alice, bob

def worst_for_bob(T_A, T_B):
    worst = None
    r = 0.0
    while r <= 60:
        for ref in (False, True):
            a, b = outcome(T_A, T_B, r, ref)
            if len(a) == 2:                       # Alice ha sia BTC sia ZEN
                return r, ref, a, b
        r += 0.5
    return worst

for T_A, T_B in [(24, 24), (48, 24)]:
    print(f"T_A={T_A}h, T_B={T_B}h -> onesto (r=2):", outcome(T_A, T_B, 2, False))
    w = worst_for_bob(T_A, T_B)
    if w:
        r, ref, a, b = w
        print(f"   ATTACCO possibile: Alice rivela a r={r}h (rimborso prima={ref}) -> Alice {a}, Bob {b}")
    else:
        print("   nessuna strategia dà ad Alice entrambe le monete")
